SELECT CASE WHEN orders.discount >= 0.32 THEN 'high' WHEN orders.discount >= 0.1 THEN 'mid' ELSE 'low' END AS discount_bucket, SUM(order_items.quantity * order_items.unit_price) AS revenue FROM order_items JOIN orders ON order_items.order_id = orders.id JOIN products ON order_items.product_id = products.id GROUP BY CASE WHEN orders.discount >= 0.32 THEN 'high' WHEN orders.discount >= 0.1 THEN 'mid' ELSE 'low' END HAVING revenue > 42 ORDER BY discount_bucket ASC;
